// hn shape: [num_directions*num_layers, batch, hidden_size] (contiguous)
// We read hn[num_layers*2-2] (forward top layer) and hn[num_layers*2-1] (backward top layer)
// weight shape: [output_size, hidden_size*2], bias shape: [output_size]
// output shape: [batch, output_size]

__global__ void fused_terminal_fc_kernel(
    const float* __restrict__ hn,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int hidden_size,
    int output_size,
    int fwd_layer_offset,  // byte offset in number of floats to start of fwd top layer
    int bwd_layer_offset   // byte offset in number of floats to start of bwd top layer
) {
    // Each thread computes one output element: output[b, o]
    int b = blockIdx.x;  // batch index
    int o = threadIdx.x + blockIdx.y * blockDim.x;  // output index
    if (b >= batch_size || o >= output_size) return;

    const float* fwd = hn + fwd_layer_offset + b * hidden_size;
    const float* bwd = hn + bwd_layer_offset + b * hidden_size;
    const float* w = weight + o * (hidden_size * 2);

    float acc = bias[o];
    // First half: forward hidden state dot product
    for (int k = 0; k < hidden_size; k++) {
        acc += fwd[k] * w[k];
    }
    // Second half: backward hidden state dot product
    for (int k = 0; k < hidden_size; k++) {
        acc += bwd[k] * w[hidden_size + k];
    }
    output[b * output_size + o] = acc;
