    torch::Tensor hn,
    torch::Tensor weight,
    torch::Tensor bias
) {
    // hn: [num_layers*2, batch, hidden_size]
    TORCH_CHECK(hn.is_cuda() && weight.is_cuda() && bias.is_cuda(), "All tensors must be CUDA");
    TORCH_CHECK(hn.dtype() == torch::kFloat32, "hn must be float32");
    TORCH_CHECK(hn.is_contiguous(), "hn must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");

