# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel: for each (batch_idx, out_idx), compute
//   bias[out_idx]
//   + dot(hn[fwd_layer, batch_idx, :], weight[out_idx, :hidden])
//   + dot(hn[bwd_layer, batch_idx, :], weight[out_idx, hidden:])
// where fwd_layer = num_layers*2 - 2, bwd_layer = num_layers*2 - 1
__global__ void bidir_fc_kernel(
    const float* __restrict__ hn,      // [num_dir_layers, batch, hidden]
    const float* __restrict__ weight,  // [out_features, hidden*2]
    const float* __restrict__ bias,    // [out_features]
    float* __restrict__ out,           // [batch, out_features]
    int batch,
    int hidden,
    int out_features,
    int fwd_layer,
    int bwd_layer
) {
    int batch_idx = blockIdx.x;
    int out_idx   = blockIdx.y * blockDim.x + threadIdx.x;
    if (batch_idx >= batch || out_idx >= out_features) return;

    // Pointers to the two terminal hidden states for this batch element
    const float* hn_fwd = hn + fwd_layer * batch * hidden + batch_idx * hidden;
    const float* hn_bwd = hn + bwd_layer * batch * hidden + batch_idx * hidden;
    // Weight row for this output neuron
    const float* w_fwd  = weight + out_idx * hidden * 2;
    const float* w_bwd  = weight + out_idx * hidden * 2 + hidden;

    float acc = bias[out_idx];
    for (int h = 0; h < hidden; ++h) {
        acc += hn_fwd[h] * w_fwd[h];
        acc += hn_bwd[h] * w_bwd[h];
    }
    out[batch_idx * out_features + out_idx] = acc;
}

