    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(),   "bias must be a CUDA tensor");
    TORCH_CHECK(hn.dtype()     == torch::kFloat32, "hn must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.dtype()   == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(hn.is_contiguous(),     "hn must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(),   "bias must be contiguous");
    TORCH_CHECK(hn.dim()     == 3, "hn must be 3D [num_dir_layers, batch, hidden]");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D [out_features, hidden*2]");
    TORCH_CHECK(bias.dim()   == 1, "bias must be 1D [out_features]");

    int num_dir_layers = hn.size(0);
    int batch          = hn.size(1);
    int hidden         = hn.size(2);
    int out_features   = weight.size(0);
    int fwd_layer      = num_dir_layers - 2;
    int bwd_layer      = num_dir_layers - 1;

    TORCH_CHECK(weight.size(1) == hidden * 2,
        "weight dim-1 must equal hidden*2");
    TORCH_CHECK(bias.size(0) == out_features,
        "bias size must equal out_features");

    auto result = torch::empty({batch, out_features}, hn.options());

    // Grid: (batch, ceil(out_features/128))
    // Block: (min(128, out_features),)
    int threads = 128;
    dim3 grid(batch, (out_features + threads - 1) / threads);
    dim3 block(threads);

    bidir_fc_kernel<<<grid, block>>>(
        hn.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        result.data_ptr<float>(),
        batch, hidden, out_features,
        fwd_layer, bwd_layer
    );

    return result;
}
